import json,base64,sys,glob,re,html
def dec(s):
    s=s+'='*(-len(s)%4)
    return base64.urlsafe_b64decode(s).decode('utf-8','replace')
def body(p):
    out=[]
    if p.get('body',{}).get('data'): out.append((p.get('mimeType'),dec(p['body']['data'])))
    for q in p.get('parts',[]) or []: out+=body(q)
    return out
def parse(path):
    d=json.loads(json.load(open(path))['result'])
    res=[]
    for m in d['messages']:
        h={x['name']:x['value'] for x in m['payload']['headers']}
        bs=body(m['payload'])
        txt=None
        for mt,b in bs:
            if mt=='text/plain': txt=b;break
        if txt is None and bs:
            txt=re.sub(r'<[^>]+>',' ',bs[0][1]); txt=html.unescape(txt)
        res.append({'id':m['id'],'date':h.get('Date'),'frm':h.get('From'),'subj':h.get('Subject'),'body':re.sub(r'\s+',' ',txt or '')})
    return res
if __name__=='__main__':
    out=[]
    for f in sys.argv[2:]: out+=parse(f)
    json.dump(out,open(sys.argv[1],'w'))
    print(len(out))
